import math

def calculate_distance(point1, point2):
    return math.sqrt((point1[0] - point2[0]) ** 2 + (point1[1] - point2[1]) ** 2)

def find_farthest_points(N, points):
    farthest_points = []
    for i in range(N):
        far_d, far_id = -1, -1
        for j in range(N):
            if i == j: 
                continue
            d = calculate_distance(points[i], points[j])
            if d > far_d:
                far_d, far_id = d, j + 1
        farthest_points.append(far_id)
    return farthest_points

